TLM.f("Sancti/06-18t",{"officium":"SS. Marci et Marcelliani Martyrum","rule":["vide C3b;","Gloria"],"fallback":"Commune/C3b","from":{"Introitus":"Commune/C3b","Tractus":"Commune/C3b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui sanctórum Mártyrum tuórum Marci et Marcelliáni natalítia cólimus; a cunctis malis imminéntibus eórum intercessiónibus liberémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 5:1-5"},{"k":"text","la":"Fratres: Justificáti ex fide, pacem habeámus ad Deum per Dóminum nostrum Jesum Christum: per quem et habémus accéssum per fidem in grátiam istam, in qua stamus, et gloriámur in spe glóriæ filiórum Dei. Non solum autem, sed et gloriámur in tribulatiónibus: scientes, quod tribulátio patiéntiam operátur, patiéntia autem probatiónem, probátio vero spem, spes autem non confúndit: quia cáritas Dei diffúsa est in córdibus nostris per Spíritum Sanctum, qui datus est nobis."}],"Graduale":[{"k":"ref","la":"Sap 3:1-2; 3:3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ."},{"k":"text","la":"Visi sunt óculis insipiéntium mori: illi autem sunt in pace.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ numquam potuit violári certámine: qui, effúso sánguine, secúti sunt Dóminum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ numquam potuit violári certámine: qui, effúso sánguine, secúti sunt Dóminum. Allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc. 11:47-51"},{"k":"text","la":"In illo témpore: Dicébat Jesus scribis et pharisǽis: Væ vobis, qui ædificátis monuménta prophetárum: patres autem vestri occidérunt illos. Profécto testificámini, quod consentítis opéribus patrum vestrórum: quóniam ipsi quidem eos occidérunt, vos autem ædificátis eórum sepúlcra. Proptérea et sapiéntia Dei dixit: Mittam ad illos prophétas et apóstolos, et ex illis occídent et persequántur: ut inquirátur sanguis ómnium prophetárum, qui effúsus est a constitutióne mundi a generatióne~ ista, a sánguine Abel usque ad sánguinem Zacharíæ, qui périit inter altáre et ædem. Ita dico vobis, requirétur ab hac generatióne."}],"Offertorium":[{"k":"ref","la":"Ps 123:7"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium: láqueus contrítus est, et nos liberáti sumus."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicáta sanctífica: et, intercedéntibus sanctis Martýribus tuis Marco et Marcelliáno, per éadem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:40; 25:34"},{"k":"text","la":"Amen, dico vobis: quod uni ex mínimis meis fecístis, mihi fecístis: veníte, benedícti Patris mei, possidéte parátum vobis regnum ab inítio sǽculi."}],"Postcommunio":[{"k":"text","la":"Salutáris tui, Dómine, múnere satiáti, súpplices exorámus: ut, cujus lætámur gustu, intercedéntibus sanctis Martýribus tuis Marco et Marcelliáno, renovémur efféctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ad6330093dbad4c6":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da nas koji svetkujemo rođendan za nebo tvojih svetih mučenika Marka i Marcelijana, njihov zagovor oslobodi od svih zala koje nam prijete.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"94e9019698340186":{"t":"Posveti, Gospodine, darove tebi prikazane i njima umilostivljen pogledaj na nas po zagovoru blaženih Marka i Marcelijana, tvojih mučenika.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f185c8d10aaf7eeb":{"t":"<i>Pomolimo se</i>.\nNasićeni, Gospodine, tvojim spasonosnim darom, ponizno molimo, da se po zagovoru svetih mučenika tvojih Marka i Marcelijana obnovimo učinkom dara koji smo radosno blagovali.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
